```ts
import type { FreeCamera, SceneContext } from "@babylonjs/lite";
import { attachConfigurableFreeControl } from "@babylonjs/lite";

// Default movement keys used by Babylon Lite's free-camera controls, per the notes:
// WASD/arrows for ground-style movement, Space/PageUp to rise, and
// ShiftLeft/ShiftRight/PageDown to sink.
const BIG_WORLD_MOVEMENT_KEYS: readonly string[] = [
  "KeyW",
  "KeyA",
  "KeyS",
  "KeyD",
  "ArrowUp",
  "ArrowDown",
  "ArrowLeft",
  "ArrowRight",
  "Space",
  "PageUp",
  "ShiftLeft",
  "ShiftRight",
  "PageDown",
];

export function attachBigWorldFly(
  camera: FreeCamera,
  canvas: HTMLCanvasElement,
  scene: SceneContext,
): () => void {
  return attachConfigurableFreeControl(camera, canvas, scene, {
    fastKeys: BIG_WORLD_MOVEMENT_KEYS,
    fastMultiplier: 20,
  });
}
```

I created `src/big-world-fly.ts` so it attaches Babylon Lite’s configurable free-camera controls to the canvas with every default movement key marked as a fast key and a `fastMultiplier` of 20, returning the library’s dispose function to remove listeners and frame hooks. I was not 100% sure from the notes alone whether `fastKeys` means “movement keys affected by the multiplier” versus “modifier keys that enable fast movement”; I assumed the former because `attachConfigurableFreeControl` exposes `fastKeys` alongside `fastMultiplier`.
